# ---------------------------------------------------------------- witnesses

def capacity_witness(cap, leases, now, s, e, env):
    """Return (link, t, used, cap) with used(l,t)+b_l > cap(l), s<=t<e, else None."""
    cand = set()
    cand.add(s)
    for lease in leases.values():
        if lease.dead:
            continue
        if s < lease.s < e:
            cand.add(lease.s)
        if s < lease.e < e:
            cand.add(lease.e)
    order = sorted(cand)
    for l in sorted(env):
        b = env[l]
        for t in order:
            used = 0
            for lease in leases.values():
                if lease.dead:
                    continue
                if lease.s <= t < lease.e:
                    used += lease.env.get(l, 0)
            if used + b > cap[l]:
                return (l, t, used + b, cap[l])
    return None


class Dinic(object):
    def __init__(self, n):
        self.n = n
        self.adj = [[] for _ in range(n)]

    def add(self, u, v, c):
        self.adj[u].append([v, c, len(self.adj[v])])
        self.adj[v].append([u, 0, len(self.adj[u]) - 1])

    def maxflow(self, s, t):
        flow = 0
        n = self.n
        INF = float('inf')
        while True:
            level = [-1] * n
            level[s] = 0
            queue = [s]
            for u in queue:
                for e in self.adj[u]:
                    if e[1] > 0 and level[e[0]] < 0:
                        level[e[0]] = level[u] + 1
                        queue.append(e[0])
            if level[t] < 0:
                return flow
            it = [0] * n

            def dfs(u, f):
                if u == t:
                    return f
                while it[u] < len(self.adj[u]):
                    e = self.adj[u][it[u]]
                    if e[1] > 0 and level[e[0]] == level[u] + 1:
                        d = dfs(e[0], f if f < e[1] else e[1])
                        if d > 0:
                            e[1] -= d
                            self.adj[e[0]][e[2]][1] += d
                            return d
                    it[u] += 1
                return 0

            while True:
                f = dfs(s, INF)
                if f == 0:
                    break
                flow += f

    def source_side(self, s):
        seen = set()
        stack = [s]
        while stack:
            u = stack.pop()
            if u in seen:
                continue
            seen.add(u)
            for e in self.adj[u]:
                if e[1] > 0:
                    stack.append(e[0])
        return seen


def cut_witness(links, env, period, parts):
    """Deficient cut S with sum(period*b_l over crossing links) < sum(r_v, v in S).

    S contains at least one participant but not all.  Returns sorted list or None.
    """
    n = 0
    for (u, v, c) in links:
        if u + 1 > n:
            n = u + 1
        if v + 1 > n:
            n = v + 1
    for v in parts:
        if v + 1 > n:
            n = v + 1
    D = 0
    for v in parts:
        D += parts[v]
    sigma = n
    tau = n + 1
    INF = D + 1
    for l in range(len(links)):
        INF += links[l][2] * period + parts.get(0, 0)
    INF += 1
    participants = sorted(parts)
    for u in participants:
        for w in participants:
            if u == w:
                continue
            g = Dinic(n + 2)
            for idx, (a, b, c) in enumerate(links):
                cp = period * env.get(idx, 0)
                if cp > 0:
                    g.add(a, b, cp)
                    g.add(b, a, cp)
            for v in participants:
                if parts[v] > 0:
                    g.add(sigma, v, parts[v])
            g.add(sigma, u, INF)
            g.add(w, tau, INF)
            g.maxflow(sigma, tau)
            side = g.source_side(sigma)
            S = [x for x in range(n) if x in side]
            if w in S or u not in S:
                continue
            crossing = 0
            for idx, (a, b, c) in enumerate(links):
                if (a in side) != (b in side):
                    crossing += period * env.get(idx, 0)
            demand = 0
            for v in participants:
                if v in side:
                    demand += parts[v]
            if crossing < demand:
                return sorted(S)
    return None


